import { useCallback } from 'react'
import { Button, Icon, Modal } from 'antd'
import { useClaims } from '../../../../../state/ClaimManagement/hooks/useClaimManagement'
import PropTypes from 'prop-types'

const ConfirmResendEmailModal = ({ claimData }) => {
  const { resendPicEmailRequest } = useClaims()
  const handleResendEmail = useCallback(() => {
    Modal.confirm({
      icon: 'notification',
      title: `Resend email for claim number ${claimData?.claim_number} ?`,
      onOk: () => resendPicEmailRequest({ claim_id: claimData.claim_id })
    })
  }, [claimData, resendPicEmailRequest])

  return (
    <Button
      onClick={handleResendEmail}
      type='link'
      disabled={claimData?.status !== 'initiated'}
    >
      <Icon type='notification' />
    </Button>
  )
}
export default ConfirmResendEmailModal

ConfirmResendEmailModal.propTypes = {
  claimData: PropTypes.object.isRequired
}
