import { Button, Icon } from 'antd'
import React, { useMemo, useState } from 'react'
import UpdateClaimStatusModal from './components/UpdateClaimStatusModal'

const UpdateClaimStatus = ({ form, claimConfigData, claimData }) => {
  const [isUpdateModalVisible, toggleUpdateModalVisibility] = useState(false)
  const possibleClaimStatuses = useMemo(() => (
    claimData &&
    claimConfigData?.claim_events?.filter(event => event.source === claimData.status)) ||
    [],
  [claimData, claimConfigData])
  return (
    <>
      <Button
        type='link'
        onClick={() => toggleUpdateModalVisibility(true)}
        disabled={!possibleClaimStatuses.length}
      >
        <Icon type='edit' />
      </Button>
      {
        isUpdateModalVisible && (
          <UpdateClaimStatusModal
            claimConfigData={claimConfigData}
            claimData={claimData}
            possibleClaimStatuses={possibleClaimStatuses}
            toggleUpdateModalVisibility={toggleUpdateModalVisibility}
          />
        )
      }
    </>
  )
}
export default UpdateClaimStatus
