import { CLAIM_AMOUNT, EVENT_CODE, REMARKS_DATA_REMARK, REMARKS_DATA_USER_REMARK } from './constants'

export const claimStatusFormValidations = {
  [EVENT_CODE]: [
    {
      required: true,
      message: 'Please select status.'
    }
  ],
  [CLAIM_AMOUNT]: [
    {
      required: true,
      message: 'Disbursement amount is required.'
    },
    {
      validator: (field, value) => Number(value?.substring(3).split('.').join('') || 0) <= 100000000,
      message: 'Amount cannot be greater than Rp 100.000.000'
    }
  ],
  [REMARKS_DATA_USER_REMARK]: ({ getFieldValue }) => [
    {
      required: ['reprocess', 'settle'].includes(getFieldValue('event_code')),
      message: 'User remark is mandatory, for claim status pending.'
    },
    {
      max: 500,
      message: 'Maximum number of characters can be 500'
    }
  ],
  [REMARKS_DATA_REMARK]: [
    {
      max: 256,
      message: 'Maximum number of characters can be 256'
    }
  ]

}
