/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Button, Upload, Icon, message, Form } from 'antd'
import { callWithTimeout } from '../../helpers/utility'

const FileUploadOnGcs = ({
  required = false,
  name = '',
  minSize = 0.01,
  maxSize = 20,
  minHeight,
  minWidth,
  accept = '',
  uploadRequest,
  isUploadSuccess,
  isUploadFailed,
  getFieldDecorator,
  label = 'Upload',
  extra,
  itemLabel,
  hasFeedback,
  buttonType
}) => {
  const [config, setConfig] = useState(null)

  const customRequest = (config) => {
    const { file } = config
    const { size } = file
    const isLtMinSize = size / 1024 / 1024 < minSize
    const isGtMaxSize = size / 1024 / 1024 > maxSize
    if (isLtMinSize) {
      message.error('File is to small, min 10kb')
      callWithTimeout(config.onError)
      setConfig(null)
      return
    }
    if (isGtMaxSize) {
      message.error(`File is to big, max ${maxSize}mb`)
      callWithTimeout(config.onError)
      setConfig(null)
      return
    }
    setConfig(config)
    uploadRequest(file)
  }

  const normFile = e => {
    if (Array.isArray(e)) {
      return e.splice(e.length - 1, e.length).map(item => ({ ...item, url: 'adfadsf' }))
    }
    return e && e.fileList && e.fileList.splice(e.fileList.length - 1, e.fileList.length)
  }

  useEffect(() => {
    if (isUploadFailed && config) {
      config.onError()
      setConfig(null)
      message.error('File upload failed')
    }
  }, [isUploadFailed])

  useEffect(() => {
    if (isUploadSuccess && config) {
      config.file.url = isUploadSuccess
      config.onSuccess(null, config.file)
      setConfig(null)
    }
  }, [isUploadSuccess])

  return (
    <>
      {
        getFieldDecorator
          ? (
            <Form.Item
              extra={extra}
              label={itemLabel}
              required={required}
            >
              {
                getFieldDecorator(name, {
                  valuePropName: 'fileList',
                  getValueFromEvent: normFile,
                  rules: [
                    {
                      required,
                      message: 'This field is required.'
                    }
                  ]
                })(
                  <Upload
                    customRequest={(config) => customRequest(config)}
                    multiple={false}
                    {...(accept && { accept })}
                  >
                    <Button
                      type={buttonType || 'default'}
                      className='width-150'
                    >
                      {label} <Icon type='cloud-upload' />
                    </Button>
                  </Upload>
                )
              }
            </Form.Item>
            )
          : (
            <Upload
              customRequest={(config) => customRequest(config)}
              multiple={false}
              {...(accept && { accept })}
              {...((isUploadSuccess || isUploadFailed) && { fileList: [] })}
            >
              <Button type={buttonType || 'default'} className='width-150'>{label} <Icon type='cloud-upload' /></Button>
            </Upload>
            )
          }
    </>
  )
}

export default FileUploadOnGcs
