import actions from './actions'

const ClaimManagementReducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case actions.CLAIMS:
    case actions.CLAIMS_SUMMARY:
    case actions.EXPORT_EXCEL:
    case actions.RESEND_PIC_EMAIL:
    case actions.UPDATE_CLAIM_STATUS:
      return { ...state, ...payload }
    default:
      return state
  }
}

export default ClaimManagementReducer
