export const getInitialFilters = () => {
  let appliedFiltersInSessionStorage
  let appliedFilters
  try {
    appliedFiltersInSessionStorage = window.sessionStorage.getItem('eb-claim-management-filters-to-be-sent')
    if (appliedFiltersInSessionStorage) {
      appliedFilters = JSON.parse(appliedFiltersInSessionStorage)
    }
  } catch (e) {
    console.error(e)
  }
  return appliedFilters || defaultClaimManagementFilters
}
