import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {

  CLAIMS_REQUEST: 'CLAIMS_REQUEST',
  CLAIMS: 'CLAIMS',
  CLAIMS_SUMMARY_REQUEST: 'CLAIMS_SUMMARY_REQUEST',
  CLAIMS_SUMMARY: 'CLAIMS_SUMMARY',
  EXPORT_EXCEL_REQUEST: 'EXPORT_EXCEL_REQUEST',
  EXPORT_EXCEL: 'EXPORT_EXCEL',
  RESEND_PIC_EMAIL_REQUEST: 'RESEND_PIC_EMAIL_REQUEST',
  RESEND_PIC_EMAIL: 'RESEND_PIC_EMAIL',
  UPDATE_CLAIM_STATUS_REQUEST: 'UPDATE_CLAIM_STATUS_REQUEST',
  UPDATE_CLAIM_STATUS: 'UPDATE_CLAIM_STATUS',

  getClaims: payload => ({
    type: actions.CLAIMS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getClaims
    }
  }),
  getClaimsSummary: payload => ({
    type: actions.CLAIMS_SUMMARY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getClaimsSummary
    }
  }),
  exportExcel: (payload) => ({
    type: actions.EXPORT_EXCEL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.exportClaimListToExcel
    }
  }),
  resendPicEmail: (payload) => ({
    type: actions.RESEND_PIC_EMAIL_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.resendPicEmail
    }
  }),
  updateClaimStatus: (payload) => ({
    type: actions.UPDATE_CLAIM_STATUS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateClaimStatus
    }
  })
}

export default actions
