import { useErrorContextValue, useGet, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Col, Form, Icon, Input, Modal, Select, Spin, Tag } from 'antd'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { RowWithMargin } from '../../../../../../../CommonComponents'
import CustomNumberFormat from '../../../../../../../CommonComponents/CustomNumberFormat'
import { useClaims } from '../../../../../../../state/ClaimManagement/hooks/useClaimManagement'
import { claimApiConfig } from '../../../../../apiConfig'
import { CLAIM_AMOUNT, EVENT_CODE, REMARKS_DATA_REMARK, REMARKS_DATA_USER_REMARK, TAG_COLOR_BY_STATUS } from './constants'
import { UpdateClaimStatusModalStyleWrapper } from './index.style'
import { getStatusLabel, getStatusLabelByEvent } from './utility'
import { claimStatusFormValidations } from './validations'

const UpdateClaimStatusModal = ({
  form,
  claimData,
  claimConfigData,
  toggleUpdateModalVisibility,
  possibleClaimStatuses
}) => {
  const [claimDetails, claimDetailsRequest] = useGet(claimApiConfig.claimDetails)
  const { getFieldValue, resetFields, validateFields, getFieldDecorator, setFields, getFieldsValue } = form
  const { updateClaimStatusRequest } = useClaims()
  const [{ UPDATE_CLAIM_STATUS_LOADER }] = useLoaderContextValue()
  const [{
    UPDATE_CLAIM_STATUS_ERROR,
    updateClaimStatusStatus,
    updateClaimStatusErrorData,
    CLAIM_DETAIL_ERROR,
    claimDetailStatus
  }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [showConfirm, setShowConfirm] = useState(false)
  const selectedEvent = getFieldValue('event_code')
  const currentStatus = getStatusLabel({ status: claimData?.status, claimConfigData })
  const statusToUpdate = getStatusLabelByEvent({ event: getFieldValue('event_code'), claimConfigData })

  // const selectedDocuments = getFieldValue('documents')
  // const documentOptions = useMemo(() => {
  //   const documents = []
  //   const { bank_details: bankDetails, ...forms } = claimDetails?.forms || {}
  //   for (const form in forms) {
  //     for (const [document, documentData] of Object.entries(forms[form])) {
  //       documents.push({ code: document, name: documentData?.display_name })
  //     }
  //   }
  //   return documents
  // }, [claimDetails])

  const getModalTitle = useCallback(() => {
    return showConfirm ? 'Claim Status Update Summary' : 'Update Claim Status'
  }, [showConfirm])

  const getOkButtonText = useCallback(() => {
    return showConfirm ? 'Update' : 'Next'
  }, [showConfirm])

  const getBackButtonText = useCallback(() => {
    return showConfirm ? 'Back' : 'Cancel'
  }, [showConfirm])

  const formItemClass = useMemo(() => {
    return showConfirm ? 'hidden' : ''
  }, [showConfirm])

  const summaryItemClass = useMemo(() => {
    return showConfirm ? '' : 'hidden'
  }, [showConfirm])

  const handleShowPreview = useCallback(() => {
    validateFields((err) => {
      if (!err) {
        setShowConfirm(true)
      }
    })
  }, [validateFields])

  const handleSubmit = useCallback(() => {
    validateFields((err, values) => {
      if (!err) {
        updateClaimStatusRequest({
          ...values,
          claim_id: claimData.claim_id,
          claim_amount: values.claim_amount?.substring(3).split('.').join('')
        })
        resetError(['updateClaimStatusStatus', 'UPDATE_CLAIM_STATUS_ERROR'])
      }
    })
  }, [resetError, validateFields, updateClaimStatusRequest, claimData])

  useEffect(() => {
    if (UPDATE_CLAIM_STATUS_ERROR && updateClaimStatusErrorData) {
      const { error } = updateClaimStatusErrorData
      const values = getFieldsValue()
      const { remarks_data: remarksError, ...remainingErrors } = error
      for (const key in remainingErrors) {
        setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(remainingErrors[key]) && remainingErrors[key].map(err => new Error(err))
          }
        })
      }
      for (const key in remarksError) {
        setFields({
          [`remarks_data.${key}`]: {
            value: values.remarks_data?.[key],
            errors: Array.isArray(remarksError[key]) && remarksError[key].map(err => new Error(err))
          }
        })
      }
      setShowConfirm(false)
    }
    if (updateClaimStatusStatus === 'success') {
      toggleUpdateModalVisibility(false)
      resetError(['updateClaimStatusStatus', 'UPDATE_CLAIM_STATUS_ERROR'])
    }
  }, [
    UPDATE_CLAIM_STATUS_ERROR,
    updateClaimStatusErrorData,
    updateClaimStatusStatus,
    getFieldsValue,
    setFields,
    toggleUpdateModalVisibility,
    resetError,
    setShowConfirm
  ])

  const handleClose = useCallback(() => {
    setShowConfirm(false)
    toggleUpdateModalVisibility(false)
    resetFields()
  }, [setShowConfirm, toggleUpdateModalVisibility, resetFields])

  const handleCancel = useCallback(() => {
    if (showConfirm) {
      setShowConfirm(false)
    } else {
      toggleUpdateModalVisibility(false)
      resetFields()
    }
  }, [resetFields, toggleUpdateModalVisibility, setShowConfirm, showConfirm])

  useEffect(() => {
    if (selectedEvent === 'reprocess' && !claimDetails) {
      claimDetailsRequest({ claim_id: claimData?.claim_id })
    }
  }, [claimData, claimDetailsRequest, selectedEvent, claimDetails])

  useEffect(() => {
    return () => resetError([
      'UPDATE_CLAIM_STATUS_ERROR',
      'updateClaimStatusStatus',
      'updateClaimStatusErrorData',
      'claimDetailStatus',
      'CLAIM_DETAIL_ERROR'
    ])
  }, [resetError])

  return (
    <Modal
      visible
      okText={getOkButtonText()}
      cancelText={getBackButtonText()}
      onCancel={handleClose}
      cancelButtonProps={{
        onClick: handleCancel
      }}
      okButtonProps={{
        style: { marginLeft: 30 }
      }}
      // onOk={handleSubmit}
      onOk={showConfirm ? handleSubmit : handleShowPreview}
      title={getModalTitle()}
    >
      <UpdateClaimStatusModalStyleWrapper>
        <Spin spinning={!!UPDATE_CLAIM_STATUS_LOADER}>
          {
            (UPDATE_CLAIM_STATUS_ERROR && !updateClaimStatusErrorData?.error) &&
              <div className='mb-5'>
                <Alert type='error' message={updateClaimStatusStatus} banner />
              </div>
          }
          {
            CLAIM_DETAIL_ERROR &&
              <div className='mb-5'>
                <Alert type='error' message={claimDetailStatus} banner />
              </div>
          }
          {
            showConfirm && (
              <div className={summaryItemClass}>
                <RowWithMargin>
                  <Col span={8}><b>Claim Number</b></Col>
                  <Col span={16}>{claimData?.claim_number}</Col>
                </RowWithMargin>
                <RowWithMargin>
                  <Col span={8}><b>Employee Name</b></Col>
                  <Col span={16}>{claimData?.employee?.name}</Col>
                </RowWithMargin>
                <RowWithMargin>
                  <Col span={8}><b>Participant Name</b></Col>
                  <Col span={16}>{claimData?.insured?.name}</Col>
                </RowWithMargin>
              </div>
            )
          }
          <Form>
            <Form.Item
              label='Claim Status'
              className={formItemClass}
            >
              {
                getFieldDecorator('event_code', {
                  rules: claimStatusFormValidations[EVENT_CODE]
                })(
                  <Select>
                    {
                      possibleClaimStatuses.map((event) => (
                        <Select.Option key={event.code} value={event.code}>{event.name}</Select.Option>
                      ))
                    }
                  </Select>
                )
              }
            </Form.Item>
            {
              form.getFieldValue('event_code') === 'settle' && (
                <>
                  {
                    showConfirm && (
                      <RowWithMargin>
                        <Col span={8}><b>Disbursement Amount</b></Col>
                        <Col span={16}>
                          {getFieldValue('claim_amount')}
                        </Col>
                      </RowWithMargin>
                    )
                  }
                  <Form.Item
                    label='Disbursement Amount'
                    className={formItemClass}
                  >
                    {
                      getFieldDecorator('claim_amount', {
                        validateTrigger: 'onChange',
                        rules: claimStatusFormValidations[CLAIM_AMOUNT]
                      })(
                        <CustomNumberFormat prefix='Rp ' decimalScale={0} allowNegative={false} />
                      )
                    }
                  </Form.Item>
                </>
              )
            }
            {
              // selectedEvent === 'reprocess' && (
              //   <Form.Item
              //     label='Documents for Re-upload'
              //     hasFeedback
              //     className={formItemClass}
              //   >
              //     {
              //       getFieldDecorator('documents')(
              //         <Select
              //           mode='multiple'
              //           loading={CLAIM_DETAIL_LOADER}
              //         >
              //           {
              //             documentOptions.map(({ code, name }) => (
              //               <Select.Option value={code} key={code}>{name}</Select.Option>
              //             ))
              //           }
              //         </Select>
              //       )
              //     }
              //   </Form.Item>
              // )
            }
            {/* {
              showConfirm && selectedEvent === 'reprocess' && (
                <RowWithMargin>
                  <Col span={8}><b>Documents for Re-upload</b></Col>
                  <Col span={16}>
                    {
                      documentOptions.filter(({ code }) => selectedDocuments?.includes(code))
                        ?.map(({ name }, index) => (
                          <Row type='flex' key={name} className='nowrap'>
                            <Col className='mr-8'>{index + 1}. </Col>
                            <Col>{name}</Col>
                          </Row>
                        ))
                    }
                  </Col>
                </RowWithMargin>
              )
            } */}
            {
              showConfirm && (
                <RowWithMargin>
                  <Col span={8}><b>Status Update</b></Col>
                  <Col span={16}>
                    <Tag
                      color={TAG_COLOR_BY_STATUS[currentStatus]}
                    >
                      {currentStatus}
                    </Tag>
                    <Icon type='arrow-right' className='mr-8' />
                    <Tag
                      color={TAG_COLOR_BY_STATUS[statusToUpdate]}
                    >
                      {statusToUpdate}
                    </Tag>
                  </Col>
                </RowWithMargin>
              )
            }
            <RowWithMargin className={summaryItemClass}>
              <Col span={8}><b>Participant Remarks</b></Col>
              <Col span={16}>
                {getFieldValue('remarks_data.user_remark')}
              </Col>
            </RowWithMargin>
            <Form.Item
              label='Participants Remarks'
              hasFeedback
              className={formItemClass}
            >
              {
                getFieldDecorator('remarks_data.user_remark', {
                  validateStatus: 'onBlur',
                  rules: claimStatusFormValidations[REMARKS_DATA_USER_REMARK]({ getFieldValue })
                })(<Input.TextArea />)
              }
            </Form.Item>
            <RowWithMargin className={summaryItemClass}>
              <Col span={8}><b>Remarks</b></Col>
              <Col span={16}>
                {getFieldValue('remarks_data.remark')}
              </Col>
            </RowWithMargin>
            <Form.Item
              label='Remarks'
              className={formItemClass}
            >
              {
                getFieldDecorator('remarks_data.remark', {
                  validateStatus: 'onBlur',
                  rules: claimStatusFormValidations[REMARKS_DATA_REMARK]
                })(<Input.TextArea />)
              }
            </Form.Item>
          </Form>
        </Spin>

      </UpdateClaimStatusModalStyleWrapper>
    </Modal>
  )
}

export default Form.create('update-claim-status-form')(UpdateClaimStatusModal)
