import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, Icon, message, Row, Spin, Table } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import { useHistory } from 'react-router'
import FileUploadOnGcs from '../../../../../../components/FileUploadOnGcs/fileUploadOnGcs'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { downloadDataFromUrl } from '../../../../../../helpers/utility'
import { EbSectionWrapper } from '../../../CommonComponents'
import { ColTextAlignRight, RowWithMargin } from '../../../CommonComponents/index.style'
import { useClaims } from '../../../state/ClaimManagement/hooks/useClaimManagement'
import { useEbClaimConfig, useFileUploadStandalone } from '../../../state/hooks'
import ClaimFilters from './components/Filters'
import ClaimsSummary from './components/Summary'
import { claimsColumns, getInitialFilters } from './utility'
import ebUrls from '../../../../../../request/urls/employeeBenefit'
import { defaultClaimManagementFilters } from './constants'

const ClaimManagement = () => {
  const history = useHistory()
  const [{
    CLAIMS_LOADER,
    RESEND_PIC_EMAIL_LOADER
  }] = useLoaderContextValue()
  const {
    claimsData,
    claimsRequest,
    claimsSummaryData,
    claimsSummaryRequest,
    exportExcelData,
    exportExcelRequest
  } = useClaims()
  const { claimConfigRequest, claimConfigData } = useEbClaimConfig()
  const [{
    CLAIMS_ERROR,
    claimsStatus,
    RESEND_PIC_EMAIL_ERROR,
    resendPicEmailStatus,
    EXPORT_EXCEL_ERROR,
    exportExcelStatus,
    UPLOAD_FILE_STANDALONE_ERROR,
    uploadFileStandaloneStatus,
    uploadFileStandaloneErrorData,
    updateClaimStatusStatus
  }] = useErrorContextValue()
  const { uploadRequest } = useFileUploadStandalone()
  const [listMetaData, setListMetaData] = useState({})
  const [filters, setFilters] = useState(getInitialFilters())
  const { resetError } = useResetError()

  const handleExportExcel = () => {
    exportExcelRequest(filters)
  }

  const handleTableChange = (params) => {
    const query = {
      page: params.current,
      per_page: params.pageSize
    }
    claimsRequest({ ...query, ...filters })
  }

  const handleUploadRequest = useCallback((file) => {
    uploadRequest({
      signedUrlBody: { identifier: 'claim', file_name: file.name, content_type: file.type },
      body: { file, url: ebUrls.uploadBulkStatusUpdateExcel },
      uploadUrl: ebUrls.uploadBulkStatusUpdateExcel,
      urlKey: 'url'
    })
  }, [uploadRequest])

  useEffect(() => {
    if (updateClaimStatusStatus === 'success') {
      message.success('Status updated successfully')
    }
    if (uploadFileStandaloneStatus === 'success') {
      message.success('File uploaded successfully.')
      resetError(['UPLOAD_FILE_STANDALONE_ERROR', 'uploadFileStandaloneStatus'])
    }
    if (UPLOAD_FILE_STANDALONE_ERROR) {
      resetError(['UPLOAD_FILE_STANDALONE_ERROR'])
    }
    if (resendPicEmailStatus === 'success') {
      message.success('Email sent successfully.')
      resetError(['resendPicEmailStatus'])
    }
    if (RESEND_PIC_EMAIL_ERROR) {
      message.error('Email could not be triggered. Please try again.')
      resetError(['RESEND_PIC_EMAIL_ERROR'])
    }
    if (exportExcelStatus === 'success' && exportExcelData && exportExcelData.url) {
      downloadDataFromUrl(exportExcelData.url)
      resetError(['exportExcelData', 'exportExcelStatus'])
    }
    if (claimsData && claimsData.meta_data) {
      setListMetaData(claimsData.meta_data)
    }
  }, [
    updateClaimStatusStatus,
    uploadFileStandaloneStatus,
    resendPicEmailStatus,
    UPLOAD_FILE_STANDALONE_ERROR,
    exportExcelStatus,
    exportExcelData,
    claimsData,
    resetError,
    RESEND_PIC_EMAIL_ERROR
  ])

  useEffect(() => {
    if (updateClaimStatusStatus === 'success') {
      claimsSummaryRequest({ page: listMetaData.page, per_page: listMetaData.page_size, ...filters })
      claimsRequest({ page: listMetaData.page, per_page: listMetaData.page_size, ...filters })
      resetError(['updateClaimStatusStatus'])
    }
  }, [
    filters,
    updateClaimStatusStatus,
    resetError,
    claimsRequest,
    claimsSummaryRequest,
    listMetaData
  ])

  useEffect(() => {
    claimsSummaryRequest(filters)
    claimsRequest(filters)
  }, [
    filters,
    claimsSummaryRequest,
    claimsRequest,
    setFilters
  ])

  useEffect(() => {
    claimConfigRequest(defaultClaimManagementFilters)
  }, [claimConfigRequest])

  return (
    <>
      <EbSectionWrapper>
        {
          CLAIMS_ERROR &&
            <div className='mb-5'>
              <Alert type='error' message={claimsStatus} banner />
            </div>
        }
        {
        EXPORT_EXCEL_ERROR &&
          <div className='mb-5'>
            <Alert type='error' message={exportExcelStatus} banner />
          </div>
        }
        {
          UPLOAD_FILE_STANDALONE_ERROR &&
            <div className='mb-5'>
              <Alert type='error' message={uploadFileStandaloneErrorData?.message || uploadFileStandaloneStatus} banner />
            </div>
          }
        <Row gutter={16} className='mb-5'>
          <Col span={16}><h2>Claim Management</h2></Col>
          <ColTextAlignRight span={4}>
            <PermissionCheckerV2 requiredPermission='ops.eb_upload_claim_file'>
              <FileUploadOnGcs
                uploadRequest={handleUploadRequest}
                buttonType='primary'
                label='Bulk Update Status'
                isUploadSuccess={uploadFileStandaloneStatus === 'success'}
                isUploadFailed={UPLOAD_FILE_STANDALONE_ERROR}
                accept='.csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel'
              />
            </PermissionCheckerV2>
          </ColTextAlignRight>
          <ColTextAlignRight span={4}>
            <PermissionCheckerV2 requiredPermission='ops.eb_view_claim_uploaded_file_list'>
              <Button
                type='primary'
                onClick={() => history.push('/employee-benefits/claim-management/file-uploads')}
              >
                <Icon type='excel' /> File Uploads <Icon type='caret-right' />
              </Button>
            </PermissionCheckerV2>
          </ColTextAlignRight>
        </Row>
        <ClaimFilters claimConfigData={claimConfigData} onFilter={setFilters} />
      </EbSectionWrapper>
      <PermissionCheckerV2 requiredPermission='ops.eb_view_claim_summary'>
        <ClaimsSummary summaryData={claimsSummaryData?.data} />
      </PermissionCheckerV2>
      <EbSectionWrapper>
        <Spin spinning={!!CLAIMS_LOADER || !!RESEND_PIC_EMAIL_LOADER}>
          <RowWithMargin>
            <Col span={6}>
              <h2>Claim List</h2>
            </Col>
            <ColTextAlignRight span={18}>
              <Button
                type='primary'
                onClick={handleExportExcel}
              >
                Export Excel <Icon type='file-excel' />
              </Button>
            </ColTextAlignRight>
          </RowWithMargin>
          <Table
            rowKey={rowData => rowData.claim_id}
            columns={claimsColumns({ history, claimConfigData })}
            bordered
            dataSource={claimsData?.data || []}
            onChange={handleTableChange}
            pagination={{
              pageSize: listMetaData.page_size,
              total: listMetaData.total_records,
              current: listMetaData.page
            }}
            scroll={{ x: true }}
          />
        </Spin>
      </EbSectionWrapper>
    </>
  )
}
export default ClaimManagement
