import React, { useCallback, useMemo } from 'react'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Alert, Col, Row, Spin, Table, Typography } from 'antd'
import { EbSectionWrapper, RowWithMargin } from '../../../../../CommonComponents'
import { claimsSummaryColumns } from './utility'

const { Text } = Typography

const ClaimsSummary = ({ summaryData }) => {
  const {
    claim_count: claimCount,
    company_count: companyCount,
    insured_count: employeeCount,
    participant_count: participantCount,
    benefit_group_summary: benefitGroupSummary,
    status_summary: { accepted, rejected, settled, initiated, reprocess }
  } = summaryData || { status_summary: {} }
  const [{ CLAIMS_SUMMARY_ERROR, claimsSummaryStatus }] = useErrorContextValue()
  const [{ CLAIMS_SUMMARY_LOADER }] = useLoaderContextValue()

  const firstRowRecords = useMemo(() => ([
    { heading: 'Total Claim', data: claimCount },
    { heading: 'Total Company', data: companyCount },
    { heading: 'Total Employee', data: employeeCount },
    { heading: 'Total Participant', data: participantCount }
  ]), [claimCount, companyCount, employeeCount, participantCount])

  const secondRowRecords = useMemo(() => ([
    { heading: 'Dokumen Diterima', data: initiated?.count },
    { heading: 'Klaim Disetujui', data: accepted?.count },
    { heading: 'Klaim Dibayarkan', data: settled?.count },
    { heading: 'Klaim Ditolak', data: rejected?.count },
    { heading: 'Klaim Ditunda', data: reprocess?.count }
  ]), [initiated, accepted, settled, rejected, reprocess])

  const renderSummaryRecord = useCallback((heading, data) => (
    <RowWithMargin key={heading}>
      <Col span={12}><Text strong>{heading}</Text> </Col>
      <Col span={12}>{data}</Col>
    </RowWithMargin>
  ), [])

  return (
    <EbSectionWrapper>
      <Spin spinning={!!CLAIMS_SUMMARY_LOADER}>
        {CLAIMS_SUMMARY_ERROR && <div className='mb-5'><Alert type='error' message={claimsSummaryStatus} banner /></div>}
        <Row>
          <Col><h2>Summary</h2></Col>
        </Row>
        <Row>
          <Col span={8}>
            {
              firstRowRecords
                .map(({ heading, data }) => renderSummaryRecord(heading, data))
            }
          </Col>
          <Col span={8}>
            {
              secondRowRecords
                .map(({ heading, data }) => renderSummaryRecord(heading, data))
            }
          </Col>
          <Col span={8}>
            <RowWithMargin>
              <Col span={24}>
                <Table
                  rowKey={row => row.name}
                  size='small'
                  columns={claimsSummaryColumns()}
                  dataSource={benefitGroupSummary || []}
                  bordered
                  pagination={benefitGroupSummary?.length > 5 ? { pageSize: 3 } : false}
                />
              </Col>
            </RowWithMargin>
          </Col>
        </Row>
      </Spin>
    </EbSectionWrapper>
  )
}
export default ClaimsSummary
