import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useClaims = () => {
  const [{ claimsData, claimsSummaryData, exportExcelData, resendPicEmailData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const claimsRequest = useCallback((payload = {}) => {
    callApi(actions.getClaims({ query: payload }))
  }, [callApi])

  const claimsSummaryRequest = useCallback((payload = {}) => {
    callApi(actions.getClaimsSummary({ query: payload }))
  }, [callApi])

  const exportExcelRequest = (payload = {}) => {
    callApi(actions.exportExcel({ query: payload }))
  }

  const resendPicEmailRequest = (payload = {}) => {
    callApi(actions.resendPicEmail({ body: payload }))
  }

  const updateClaimStatusRequest = (payload = {}) => {
    callApi(actions.updateClaimStatus({ body: payload }))
  }

  return {
    claimsRequest,
    claimsData,
    claimsSummaryRequest,
    claimsSummaryData,
    exportExcelRequest,
    exportExcelData,
    resendPicEmailData,
    resendPicEmailRequest,
    updateClaimStatusRequest
  }
}
