import { Button, Icon, Modal, Timeline, Typography } from 'antd'
import React, { useCallback } from 'react'
import { RowWithMargin } from '../../../../../CommonComponents'
import PropTypes from 'prop-types'

const { Text } = Typography

const RemarksModal = ({ remarks, claimConfigData, title }) => {
  const handleShowRemarks = useCallback(() => {
    const content = (
      <RowWithMargin>
        <Timeline>
          {Array.isArray(remarks) && remarks.sort((remark1, remark2) => remark2.id - remark1.id).map(({ remark, id, ...remainingFields }) => (
            <Timeline.Item key={id} color='green'>
              <Text strong>
                {claimConfigData?.claim_status?.find(claimStatus => claimStatus.code === remainingFields.from_status)?.name || remainingFields.from_status}
                &nbsp;<Icon type='arrow-right' />&nbsp;
                {claimConfigData?.claim_status?.find(claimStatus => claimStatus.code === remainingFields.to_status)?.name || remainingFields.to_status}
              </Text>
              <p>
                <Text code>{remark}</Text>
                <br />
                <Text disabled>
                  By - {remainingFields.added_by_name}
                </Text>
              </p>
            </Timeline.Item>
          ))}
        </Timeline>
      </RowWithMargin>
    )
    Modal.error({
      title,
      content,
      okText: 'Close',
      icon: null
    })
  }, [remarks, claimConfigData, title])

  return (
    <>
      <Button
        type='link'
        onClick={handleShowRemarks}
        disabled={!remarks?.length}
      >
        <Icon type='eye' />
      </Button>
    </>
  )
}
export default RemarksModal

RemarksModal.propTypes = {
  remarks: PropTypes.array.isRequired,
  claimConfigData: PropTypes.object.isRequired
}
