import { Row, Col, Form, DatePicker, Button, Icon, Input, Select, Spin } from 'antd'
import { horizontalLayout } from '../../../../../utils/formLayout'
import { RowWithMargin } from '../../../../../CommonComponents'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect } from 'react'
import { defaultClaimManagementFilters } from '../../constants'
import moment from 'moment-timezone'

const { RangePicker } = DatePicker
const { Item } = Form

const Filters = ({ form, onFilter, claimConfigData, ...props }) => {
  const { getFieldDecorator, setFieldsValue } = form
  const [{ CLAIMS_LOADER, CLAIMS_SUMMARY_LOADER }] = useLoaderContextValue()

  const handleResetFilter = () => {
    onFilter()
    form.resetFields()
    window.sessionStorage.setItem('eb-claim-management-filters', JSON.stringify({}))
    window.sessionStorage.setItem('eb-claim-management-filters-to-be-sent', JSON.stringify({}))
  }

  const getDateFromDateRange = useCallback((range, index) => (
    (Array.isArray(range) && range.length) ? range[index]?.format('YYYY-MM-DD') : undefined
  ), [])

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        const { created_at: createdAtRange, updated_at: updatedAtRange, ...toBeSentValues } = values
        window.sessionStorage.setItem('eb-claim-management-filters', JSON.stringify({
          ...toBeSentValues,
          created_at: Array.isArray(createdAtRange) ? createdAtRange.map(date => date.format('YYYY-MM-DD')) : undefined,
          updated_at: Array.isArray(updatedAtRange) ? updatedAtRange.map(date => date.format('YYYY-MM-DD')) : undefined
        }))
        toBeSentValues.created_at_start_date = getDateFromDateRange(createdAtRange, 0)
        toBeSentValues.created_at_end_date = getDateFromDateRange(createdAtRange, 1)
        toBeSentValues.updated_at_start_date = getDateFromDateRange(updatedAtRange, 0)
        toBeSentValues.updated_at_end_date = getDateFromDateRange(updatedAtRange, 1)
        window.sessionStorage.setItem('eb-claim-management-filters-to-be-sent', JSON.stringify(toBeSentValues))
        onFilter(toBeSentValues)
      }
    })
  }

  useEffect(() => {
    const sessionFilters = window.sessionStorage.getItem('eb-claim-management-filters')
    try {
      if (sessionFilters) {
        const { created_at: createdAt, updated_at: updatedAt, ...filters } = JSON.parse(sessionFilters)
        setFieldsValue({
          updated_at: Array.isArray(updatedAt) ? updatedAt.map(date => moment(date)) : undefined,
          created_at: Array.isArray(createdAt) ? createdAt.map(date => moment(date)) : undefined,
          ...filters
        })
      } else {
        setFieldsValue({
          updated_at: [
            moment(defaultClaimManagementFilters.updated_at_start_date),
            moment(defaultClaimManagementFilters.update_at_end_date)
          ]
        })
      }
    } catch (e) {
      console.error(e)
    }
  }, [setFieldsValue])

  return (
    <Spin spinning={!!CLAIMS_LOADER || !!CLAIMS_SUMMARY_LOADER}>
      <RowWithMargin>
        <Form
          onSubmit={handleSubmit}
          {...horizontalLayout}
          labelCol={{ xs: 24, sm: 7 }}
        >
          <Row gutter={16}>
            <Col span={8}>
              <h3>Filters</h3>
            </Col>
            <Col offset={12} span={4}>
              <Item>
                <Button
                  type='danger'
                  onClick={handleResetFilter}
                >
                  Clear Filters <Icon type='delete' />
                </Button>
              </Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={10}>
              <Item label='Claim Number' labelAlign='left'>
                {
                getFieldDecorator('claim_number', {})(
                  <Input placeholder='Eg - EBKLM-2312' allowClear />
                )
              }
              </Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={10}>
              <Item label='Employee Name' labelAlign='left'>
                {
                getFieldDecorator('employee_name', {
                  rules: [
                    {
                      max: 128,
                      message: 'Employee name should not be greater than 128 characters'
                    }
                  ]
                })(
                  <Input placeholder='Andika Rama' allowClear />
                )
              }
              </Item>
            </Col>
            <Col span={10} id='select-benefit-groups'>
              <Item
                label='Benefit'
                labelAlign='left'
              >
                {
                  getFieldDecorator('benefit_group')(
                    <Select
                      mode='multiple'
                      showArrow
                      optionFilterProp='children'
                      getPopupContainer={() => document.getElementById('select-benefit-groups')}
                      filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      {
                        claimConfigData?.benefit_groups?.map(({ slug, group_name: groupName }) => (
                          <Select.Option value={slug} key={slug}>
                            {groupName}
                          </Select.Option>
                        ))
                      }
                      <Select.Option value='Outpatient'>
                        Outpatient
                      </Select.Option>
                    </Select>
                  )
                }
              </Item>
            </Col>

          </Row>
          <Row gutter={16}>
            <Col span={10}>
              <Item
                label='Participant Name'
                labelAlign='left'
              >
                {
                  getFieldDecorator('insured_name', {
                    rules: [
                      {
                        max: 128,
                        message: 'Participant name should not be greater than 128 characters'
                      }
                    ]
                  })(
                    <Input placeholder='Andreas Wijaya' />
                  )
                }

              </Item>
            </Col>
            <Col span={10}>
              <Item
                label='Claim Status'
                labelAlign='left'
              >
                {
                  getFieldDecorator('status')(
                    <Select>
                      {
                        claimConfigData?.claim_status?.map(({ code, name }) => (
                          <Select.Option value={code} key={code}>
                            {name}
                          </Select.Option>
                        ))
                      }
                    </Select>
                  )
                }
              </Item>
            </Col>

          </Row>

          <Row gutter={16}>
            <Col span={10}>
              <Item label='Company' labelAlign='left'>
                {
                getFieldDecorator('company_name', {
                  rules: [
                    {
                      max: 128,
                      message: 'Company name should not be greater than 128 characters'
                    }
                  ]
                })(
                  <Input placeholder='Pasarpolis ...' />
                )
              }
              </Item>
            </Col>
            <Col span={10}>
              <Item label='Created At' labelAlign='left'>
                {
                  getFieldDecorator('created_at', {})(
                    <RangePicker allowClear />
                  )
                }
              </Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={10}>
              <Item label='Insurance Provider' labelAlign='left'>
                {
                getFieldDecorator('insurance_provider')(
                  <Select>
                    {
                      claimConfigData?.insurance_providers
                        ?.sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
                        ?.map(provider => (
                          <Select.Option value={provider} key={provider}>
                            {provider}
                          </Select.Option>
                        ))
                    }
                  </Select>
                )
              }
              </Item>
            </Col>

            <Col span={10}>
              <Item label='Updated At' labelAlign='left'>
                {
                getFieldDecorator('updated_at')(
                  <RangePicker allowClear />
                )
              }
              </Item>
            </Col>
            <Col span={4}>
              <Item>
                <Button type='primary' htmlType='submit'>Apply Filters <Icon type='filter' /></Button>
              </Item>
            </Col>
          </Row>
        </Form>
      </RowWithMargin>
    </Spin>
  )
}
export default Form.create({ name: 'insurer-filter' })(Filters)
